const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const state={user:null,departments:[],groups:[],users:[],tasks:[],taskHistory:[],cases:[],missingReports:[],snapshots:[],settings:{},auditLogs:[],auditCursor:'',auditDatesInitialized:false,runtimeLogs:[],runtimeCursor:'',runtimeLastSeq:0,runtimeStream:null,taskConsoleView:'active',taskConsoleTasks:[],taskConsoleCursor:'',taskConsoleTimer:null,taskListTimer:null,resourceSnapshot:null,resourceHistory:[],resourceRange:'1h',resourceTimer:null,resourceHistoryTimer:null,editingReportId:'',editingReportData:null,serverClock:{baseMs:0,receivedAt:0}};
const ROLES=['employee','group_leader','director','minister','admin'];
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function roleText(r){return {employee:'员工',group_leader:'组长',director:'主任',minister:'部长',admin:'管理员'}[r]||r||''}
function formatTimestamp(value){return String(value||'').replace('T',' ')}
function submissionTimeValue(value){return formatTimestamp(value)}
function formatShanghaiTimestamp(date){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(date).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return `${parts.year}-${parts.month}-${parts.day} ${parts.hour}:${parts.minute}:${parts.second}`}
function renderSubmissionTime(){const input=$('#submissionTime');if(!input||state.editingReportId||!state.serverClock.baseMs)return;input.value=formatShanghaiTimestamp(new Date(state.serverClock.baseMs+Date.now()-state.serverClock.receivedAt))}
async function refreshShanghaiClock(){const clock=await requestJson('/api/time');state.serverClock={baseMs:Date.parse(`${clock.now}+08:00`),receivedAt:Date.now()};renderSubmissionTime()}
function riskText(r){return {high:'高风险',medium:'中风险',low:'低风险',normal:'正常',unknown:'未知'}[r]||r||''}
function checkerText(id){return {report_duplicate_check:'日报查重',quality_check:'日报质量',testcase_check:'测试用例核验',code_check:'代码记录',document_check:'文档记录'}[id]||id}
function canManage(){return ['group_leader','director','minister'].includes(state.user?.role)}
function canExportReports(){return ['group_leader','director','minister'].includes(state.user?.role)}
function isBusiness(){return ['employee','group_leader','director','minister'].includes(state.user?.role)}
function isAdmin(){return state.user?.role==='admin'}
async function requestJson(url,opt={}){const r=await fetch(url,{cache:'no-store',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'请求失败');return d}
async function requestForm(url,form,method='POST'){const r=await fetch(url,{method,body:form});const d=await r.json();if(!r.ok)throw new Error(d.error||'请求失败');return d}
async function downloadFile(url,name){const r=await fetch(url);if(!r.ok)throw new Error('下载失败');const b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function canAccessPanel(id){
  if(!state.user)return false;
  if(['taskConsole','resourceMonitor','admin','auditLogs','runtimeLogs'].includes(id))return isAdmin();
  if(['manager','taskHistory','snapshots'].includes(id))return canManage();
  if(id==='periodicReports')return canExportReports();
  return ['employee','myReports'].includes(id)&&isBusiness();
}
function defaultPanel(){return isAdmin()?'admin':'employee'}
function switchPanel(id){
  if(!canAccessPanel(id)||!document.getElementById(id))return false;
  const activeTab=$$('.tab').find(t=>t.dataset.panel===id);
  $$('.tab').forEach(t=>{const active=t.dataset.panel===id;t.classList.toggle('active',active);t.setAttribute('aria-current',active?'page':'false')});
  $$('.panel').forEach(p=>{const active=p.id===id;p.classList.toggle('active',active);p.setAttribute('aria-hidden',active?'false':'true')});
  document.title=`${activeTab?.textContent?.trim()||'日报核验'} · 日报核验系统`;
  window.scrollTo({top:0,behavior:'auto'});
  stopTaskConsolePolling();
  stopTaskListPolling();
  stopResourceMonitorPolling();
  stopRuntimeLogStream();
  if(id==='taskHistory'&&canManage())refreshTaskHistory().catch(()=>{});
  if(id==='manager'&&canManage())refreshTasks().finally(scheduleTaskListPolling);
  if(id==='taskConsole'&&isAdmin())activateTaskConsole();
  if(id==='resourceMonitor'&&isAdmin())activateResourceMonitor();
  if(id==='auditLogs'&&isAdmin()){ensureAuditDates();refreshAuditLogs(true).catch(err=>setAdminMessage('#auditMessage',err.message))}
  if(id==='runtimeLogs'&&isAdmin())activateRuntimeLogs();
  return true;
}
function showAuthMode(m){$('#loginForm').classList.toggle('hidden',m!=='login');$('#registerForm').classList.toggle('hidden',m!=='register')}
function departmentOptions(current='',empty=true){return `${empty?'<option value="">选择部门</option>':''}${state.departments.map(d=>`<option value="${escapeHtml(d.department_id)}" ${d.department_id===current?'selected':''}>${escapeHtml(d.name)}</option>`).join('')}`}
function groupOptions(current='',departmentId='',empty=true){const rows=state.groups.filter(g=>!departmentId||g.department_id===departmentId);return `${empty?'<option value="">选择小组</option>':''}${rows.map(g=>`<option value="${escapeHtml(g.group_id)}" ${g.group_id===current?'selected':''}>${escapeHtml(g.name)}</option>`).join('')}`}
function roleOptions(current){return ROLES.map(r=>`<option value="${r}" ${r===current?'selected':''}>${roleText(r)}</option>`).join('')}
function renderReportRoleOptions(){const select=$('#reportRole');if(!select||!state.user)return;const directReportRole={group_leader:'employee',director:'group_leader',minister:'director'}[state.user.role]||'';select.innerHTML='<option value="">全部</option>'+(directReportRole?`<option value="${directReportRole}">仅${roleText(directReportRole)}</option>`:'');select.disabled=!directReportRole}
function applyRoleUi(){
  document.body.classList.toggle('authenticated',!!state.user);document.body.classList.toggle('is-business',isBusiness());document.body.classList.toggle('can-manage',canManage());document.body.classList.toggle('can-export-reports',canExportReports());document.body.classList.toggle('is-admin',isAdmin());document.body.classList.toggle('can-upload-snapshot',['group_leader','director'].includes(state.user?.role));
  if(!state.user)return;
  $('#statusPill').textContent=`${state.user.display_name||state.user.username} · ${roleText(state.user.role)}`;
  $('#orgChain').textContent=[state.user.department_name,state.user.group_name].filter(Boolean).join(' / ');
  if(isBusiness()){
    renderReportRoleOptions();
    const f=$('#reportForm'),submissionTime=$('#submissionTime');submissionTime.type='text';submissionTime.name='';submissionTime.readOnly=true;submissionTime.title='服务器上海时间，不能手动修改';$('#submissionTimeNote').textContent='以提交时服务器上海时间为准；09:00 前提交的日报归入前一日查重，09:00 起归入当天。';f.elements.name.value=state.user.display_name||'';f.elements.role_text.value=roleText(state.user.role);f.elements.department.value=state.user.department_name||'全公司';f.elements.group.value=state.user.group_name||'—';if(!state.editingReportId)renderSubmissionTime();
    const manager=f.elements.manager;manager.value=state.user.manager_display_name||(state.user.is_test_account?'测试负责人':(state.user.role==='minister'?'无（最高领导）':''));manager.readOnly=!!state.user.manager_display_name||state.user.role==='minister';manager.required=state.user.role!=='minister'&&!state.user.is_test_account;
    renderDepartmentScopeOptions();
  }
  const activePanel=$('.panel.active')?.id;
  if(!canAccessPanel(activePanel))switchPanel(defaultPanel());
}
async function refreshAuth(){const data=await requestJson('/api/auth/me');state.user=data.user||null;await refreshPublicOrganisation();applyRoleUi();if(!state.user)return;await refreshShanghaiClock();if(isBusiness())await refreshMyReports();if(canManage())await Promise.all([refreshStatus(),refreshTasks(),refreshTaskHistory(),refreshResults(),refreshSnapshots()]);if(isAdmin())await refreshAdmin()}
async function refreshPublicOrganisation(){state.departments=await requestJson('/api/public/departments').catch(()=>[]);state.groups=await requestJson('/api/public/groups').catch(()=>[]);$('#registerDepartment').innerHTML=departmentOptions('',true);updateRegisterGroups()}
function updateRegisterGroups(){const did=$('#registerDepartment').value;$('#registerGroup').innerHTML=groupOptions('',did,true)}
function renderDepartmentScopeOptions(){const s=$('#departmentScope');if(!s||!state.user)return;if(['group_leader','director'].includes(state.user.role)){s.innerHTML=`<option value="${escapeHtml(state.user.department_id)}">${escapeHtml(state.user.department_name)}</option>`;s.disabled=true}else{s.innerHTML=`<option value="">全公司</option>${state.departments.map(d=>`<option value="${escapeHtml(d.department_id)}">${escapeHtml(d.name)}</option>`).join('')}`;s.disabled=false}}
function reportQuery(){return new URLSearchParams({name:$('#reportName').value.trim(),start:$('#reportStart').value,end:$('#reportEnd').value,role:$('#reportRole').value})}
async function refreshMyReports(){if(!isBusiness())return;const rows=await requestJson('/api/my/reports?'+reportQuery());$('#myReportList').innerHTML=rows.map(r=>`<tr><td>${escapeHtml(r.report_date)}</td><td>${escapeHtml(formatTimestamp(r.created_at))}${r.updated_at?`<br><span class="small-note">最后修改：${escapeHtml(formatTimestamp(r.updated_at))}</span>`:''}</td><td>${escapeHtml(r.employee_name)}</td><td><span class="role-pill">${roleText(r.submitter_role)}</span></td><td>${escapeHtml(r.department_name||'全公司')}<br><span class="small-note">${escapeHtml(r.group_name||'—')}</span></td><td>${escapeHtml(r.title_summary)}</td><td>已提交</td><td>${(r.artifacts||[]).map(a=>`<button class="secondary mini" data-artifact="${escapeHtml(a.artifact_id)}" data-file="${escapeHtml(a.original_filename)}">${escapeHtml(a.original_filename)}</button>`).join(' ')||'-'}</td><td><button class="secondary" data-download-report="${escapeHtml(r.report_id)}" data-file="${escapeHtml(r.original_filename)}">下载</button>${r.can_edit?` <button class="secondary" data-edit-report="${escapeHtml(r.report_id)}">更改</button>`:''}</td></tr>`).join('')||'<tr><td colspan="9">暂无日报记录</td></tr>'}
async function refreshStatus(){const s=await requestJson('/api/status');$('#inputCount').textContent=s.metadata?.report_count??'-';$('#resultCount').textContent=s.result_count??'-';$('#highRiskCount').textContent=s.high_risk_count??'-';$('#errorCount').textContent=s.error_count??'-'}
function taskName(t){if(t.trigger_source==='system_daily'&&t.report_date&&t.task_date){const format=d=>`${Number(d.slice(5,7))}.${Number(d.slice(8,10))}`;return `${format(t.report_date)} 日报自动查重（${format(t.task_date)} 执行）`}return t.task_name||t.task_id}
function setCheckProgress(active,message=''){const status=$('#taskMessage');status.textContent=message;status.classList.toggle('loading',active);$('#runCheck').disabled=active;$('#taskForm').querySelector('button[type="submit"]').disabled=active}
function duplicateUsageText(summary={},fallbackCurrent=0,fallbackTotal=0){const checked=summary.local_duplicate_checked_count??fallbackCurrent??0,total=summary.local_duplicate_total_count??(fallbackTotal||summary.report_count||0);return `本地查重：${Number(checked)}/${Number(total)} · LLM复核：${Number(summary.llm_review_count||0)} · 降级本地判断：${Number(summary.degraded_local_count||0)}`}
function checkCompletionMessage(result,startedAt){const seconds=((Date.now()-startedAt)/1000).toFixed(1),summary=result.summary||{};return `查重完成，用时 ${seconds} 秒：日报 ${summary.report_count||0} 份，高风险 ${summary.high_risk_count||0} 份，缺报 ${summary.missing_report_count||0} 条；${duplicateUsageText(summary)}。`}
const delay=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function waitForCheckTask(taskId,startedAt){
  while(true){
    if(document.hidden){await new Promise(resolve=>document.addEventListener('visibilitychange',resolve,{once:true}));continue}
    const task=await requestJson(`/api/tasks/${encodeURIComponent(taskId)}/status`);
    if(task.status==='finished')return task;
    if(['failed','cancelled','terminated'].includes(task.status)){const suffix=task.partial_available?'（已保留部分结果）':'';throw new Error((task.error_message||`后台查重任务${task.status==='cancelled'?'已取消':task.status==='terminated'?'已被管理员强制终止':'失败'}`)+suffix)}
    const progress=task.progress_total?` ${task.progress_current||0}/${task.progress_total}（${Math.floor((task.progress_current||0)*100/task.progress_total)}%）`:'';
    const runningLabel=task.status==='queued'?'任务排队中':task.status==='paused'?'任务已被管理员暂停':'后台查重中';
    setCheckProgress(true,`${runningLabel}${progress}：${task.progress_message||''}；关闭或刷新页面不会中断任务…`);
    await delay(Date.now()-startedAt<60000?2000:5000);
  }
}
function taskStatusText(v){return {queued:'排队中',running:'运行中',pausing:'暂停中',paused:'已暂停',cancelling:'取消中',terminating:'终止中',deleting:'正在停止并删除',finished:'已完成',failed:'失败',cancelled:'已取消',terminated:'已强制终止'}[v]||v||'未知'}
function taskProgressMarkup(task){const status=task.effective_status||task.status,current=Number(task.progress_current||0),total=Number(task.progress_total||0),active=['queued','running','paused'].includes(task.status),percent=total?Math.max(0,Math.min(100,current*100/total)):(task.status==='finished'?100:0);if(!active&&!total)return '';const count=total?`${current}/${total} · ${percent.toFixed(percent%1?1:0)}%`:'准备中';return `<div class="user-task-progress" data-status="${escapeHtml(status)}"><div class="task-progress-copy"><span>${escapeHtml(task.progress_message||taskStatusText(status))}</span><strong>${escapeHtml(count)}</strong></div><div class="task-progress-track ${active&&!total?'indeterminate':''}" role="progressbar" aria-label="${escapeHtml(taskName(task))}进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-valuetext="${escapeHtml(total?`${current}/${total}，${percent.toFixed(1)}%`:(task.progress_message||taskStatusText(status)))}"><span style="width:${percent}%"></span></div></div>`}
function taskRows(tasks,{view=true}={}){return tasks.map(t=>{const automatic=t.trigger_source==='system_daily',finished=t.status==='finished',active=['queued','running','paused'].includes(t.status),hasResults=finished||t.partial_available,resultActions=hasResults?`${view?`<button class="secondary" data-view-task="${escapeHtml(t.task_id)}" data-task-name="${escapeHtml(taskName(t))}">查看${finished?'':'部分'}结果</button>`:''}${finished?`<button class="secondary" data-xlsx-task="${escapeHtml(t.task_id)}">Excel</button><button class="secondary" data-missing-task="${escapeHtml(t.task_id)}">缺报名单</button><button class="secondary" data-docx-task="${escapeHtml(t.task_id)}">Word</button>`:''}`:'<span class="small-note">暂无结果</span>',retry=['failed','cancelled'].includes(t.status)?`<button class="secondary" data-retry-task="${escapeHtml(t.task_id)}">重试</button>`:'',cancel=active&&(!automatic||state.user?.role==='admin')?`<button class="danger-button" data-cancel-task="${escapeHtml(t.task_id)}">取消</button>`:'',remove=!automatic?`<button class="danger-button" data-delete-task="${escapeHtml(t.task_id)}" data-delete-active="${active?'1':'0'}">${active?'停止并删除':'删除'}</button>`:'';return `<tr><td>${escapeHtml(taskName(t))}${automatic?'<br><span class="small-note">系统自动任务</span>':''}</td><td><span class="task-state ${escapeHtml(t.effective_status||t.status)}">${escapeHtml(taskStatusText(t.effective_status||t.status))}</span>${taskProgressMarkup(t)}${t.error_message?`<br><span class="small-note">${escapeHtml(t.error_message)}${t.partial_available?'（有部分结果）':''}</span>`:''}</td><td>日报 ${t.summary?.report_count||0} / 高风险 ${t.summary?.high_risk_count||0} / 缺报 ${t.summary?.missing_report_count||0}<br><span class="small-note">${duplicateUsageText(t.summary||{},t.progress_current||0,t.progress_total||0)}</span></td><td>${escapeHtml(t.created_at)}</td><td><div class="task-actions">${resultActions}${retry}${cancel}${remove}</div></td></tr>`}).join('')||'<tr><td colspan="5">暂无任务</td></tr>'}
async function refreshTasks(){const q=new URLSearchParams({status:$('#taskStatus').value,start:$('#taskStart').value,end:$('#taskEnd').value});state.tasks=await requestJson('/api/tasks?'+q);$('#taskList').innerHTML=taskRows(state.tasks,{view:true})}
function stopTaskListPolling(){if(state.taskListTimer){clearTimeout(state.taskListTimer);state.taskListTimer=null}}
function scheduleTaskListPolling(){stopTaskListPolling();if(document.hidden||$('.panel.active')?.id!=='manager'||!canManage())return;state.taskListTimer=setTimeout(async()=>{try{await refreshTasks()}catch(_err){}finally{scheduleTaskListPolling()}},2000)}
async function refreshTaskHistory(){state.taskHistory=await requestJson('/api/tasks?include_hidden=1');$('#taskHistoryList').innerHTML=taskRows(state.taskHistory,{view:false})}
async function refreshResults(taskId='',taskName=''){let selectedId=taskId;if(!selectedId){const tasks=await requestJson('/api/tasks');selectedId=tasks[0]?.task_id||'';taskName=tasks[0]?.task_name||selectedId}state.cases=selectedId?await requestJson(`/api/tasks/${encodeURIComponent(selectedId)}/results`):[];state.missingReports=selectedId?await requestJson(`/api/tasks/${encodeURIComponent(selectedId)}/missing-reports`):[];$('#selectedTaskLabel').textContent=selectedId?`任务 ${taskName||selectedId} 的结果`:'最近一次任务结果';renderResults();renderMissingReports()}
function renderResults(){const q=$('#searchBox').value.trim().toLowerCase(),risk=$('#riskFilter').value,date=$('#dateFilter').value;const rows=state.cases.filter(x=>(!date||x.report_date===date)&&(!risk||x.overall_risk===risk));const visible=rows.filter(x=>[x.employee_name,x.department_name,x.report_date,x.title_summary,JSON.stringify(x.checks||[])].join(' ').toLowerCase().includes(q));$('#reviewCaseList').innerHTML=visible.map(renderCase).join('')||'<div class="card">暂无结果</div>'}
function renderMissingReports(){const rows=state.missingReports||[];$('#missingReportLabel').textContent=`缺报人员（${rows.length} 条）`;$('#missingReportList').innerHTML=rows.map(r=>`<tr><td>${escapeHtml(r.report_date)}</td><td>${escapeHtml(r.employee_name)}</td><td>${escapeHtml(roleText(r.role))}</td><td>${escapeHtml(r.department_name||'—')} / ${escapeHtml(r.group_name||'—')}</td></tr>`).join('')||'<tr><td colspan="4">所选工作日内无缺报人员</td></tr>'}
function renderCase(c){return `<article class="case-card"><div class="case-head"><div><h2>${escapeHtml(c.employee_name||'未命名')}</h2><p>${escapeHtml(c.department_name||'')} · 查重归属：${escapeHtml(c.report_date||'')}</p><p class="small-note">提交时间：${escapeHtml(formatTimestamp(c.submitted_at)||'—')}</p><p>${escapeHtml(c.title_summary||'')}</p></div><span class="badge ${escapeHtml(c.overall_risk)}">${riskText(c.overall_risk)}</span></div><div class="check-grid">${(c.checks||[]).filter(x=>x.triggered).map(renderCheck).join('')}</div></article>`}
function renderMatchDetails(f){const matches=f.details?.matches;if(!Array.isArray(matches)||!matches.length)return '';const isToken=['token_similarity','code_token_similarity'].includes(f.details?.engine),label=f.details?.engine==='code_token_similarity'?'代码 Token 查重':isToken?'文档 Token 查重':'JPlag 返回',rows=matches.map(m=>`<tr><td>${escapeHtml(m.source_name||'当前提交')}</td><td>${escapeHtml(m.matched_name||'历史提交')}</td><td>${(Number(m.similarity||0)*100).toFixed(1)}%</td>${isToken?`<td>${Number(m.matched_token_count||0)}</td>`:''}</tr>`).join('');return `<details class="match-results"><summary>${label}的 ${matches.length} 项匹配明细</summary><div class="table-wrap compact"><table><thead><tr><th>当前提交</th><th>历史提交</th><th>相似度</th>${isToken?'<th>相同词数</th>':''}</tr></thead><tbody>${rows}</tbody></table></div></details>`}
function renderCheck(c){const findings=c.findings||[],fs=findings.map(f=>`<tr><td>${escapeHtml(f.target_name)}</td><td>${escapeHtml(f.matched_target_name||'')}</td><td>${Number(f.score||0).toFixed(2)}</td><td><span class="badge ${escapeHtml(f.risk_level)}">${riskText(f.risk_level)}</span></td><td>${escapeHtml(f.reason||'')}</td></tr>`).join(''),matchDetails=findings.map(renderMatchDetails).join('');return `<section class="check-card"><div class="check-head"><strong>${checkerText(c.checker_id)}</strong><span class="badge ${escapeHtml(c.risk_level)}">${riskText(c.risk_level)}</span></div><p>${escapeHtml(c.summary||'')}</p>${matchDetails}${fs?`<div class="table-wrap compact"><table><thead><tr><th>当前对象</th><th>匹配对象</th><th>分值</th><th>风险</th><th>原因</th></tr></thead><tbody>${fs}</tbody></table></div>`:''}</section>`}
function rowHtml(fields){return `<tr>${fields.map(f=>`<td><input name="${f.name}" placeholder="${escapeHtml(f.placeholder||'')}" value="${escapeHtml(f.value||'')}" /></td>`).join('')}<td><button type="button" class="secondary remove-row">删除</button></td></tr>`}
function collectRows(sel){return $$(sel+' tr').map(r=>{const o={};r.querySelectorAll('input').forEach(i=>o[i.name]=i.value.trim());return o}).filter(o=>Object.values(o).some(Boolean))}
function resetReportForm(){state.editingReportId='';state.editingReportData=null;const form=$('#reportForm');form.reset();$('#codeBody').innerHTML='';$('#documentBody').innerHTML='';['#codeFiles','#documentFiles','#testcaseFiles'].forEach(s=>{const input=$(s);if(input)input.value=''});$('#submitReport').textContent='提交日报';$('#cancelReportEdit').classList.add('hidden');$('#formMessage').textContent='';applyRoleUi()}
async function startReportEdit(reportId){const report=await requestJson(`/api/my/reports/${encodeURIComponent(reportId)}`);state.editingReportId=reportId;state.editingReportData=report;const form=$('#reportForm');form.elements.name.value=report.employee_name||'';form.elements.role_text.value=roleText(report.submitter_role);form.elements.department.value=report.department_name||'全公司';form.elements.group.value=report.group_name||'—';$('#submissionTime').value=submissionTimeValue(report.created_at)||'';form.elements.manager.value=report.manager||'';form.elements.title_summary.value=report.title_summary||'';form.elements.work_description.value=report.work_description||'';$('#codeBody').innerHTML=(report.code_items||[]).map(item=>rowHtml([{name:'file_name',placeholder:'main.py',value:item.file_name},{name:'language',placeholder:'python',value:item.language},{name:'work_type',placeholder:'修改',value:item.work_type},{name:'description',placeholder:'说明',value:item.description}])).join('');$('#documentBody').innerHTML=(report.document_items||[]).map(item=>rowHtml([{name:'document_name',placeholder:'设计说明',value:item.document_name},{name:'document_type',placeholder:'docx',value:item.document_type},{name:'work_type',placeholder:'修改',value:item.work_type},{name:'description',placeholder:'说明',value:item.description}])).join('');$('#submitReport').textContent='保存更改';$('#cancelReportEdit').classList.remove('hidden');$('#formMessage').textContent=`正在更改查重归属为 ${report.report_date} 的日报；已有附件会保留。`;switchPanel('employee');window.scrollTo({top:0,behavior:'smooth'})}
async function refreshSnapshots(){if(!canManage())return;state.snapshots=await requestJson('/api/testcase-snapshots');$('#snapshotList').innerHTML=state.snapshots.map(s=>`<tr><td>${escapeHtml(s.department_name||'')}</td><td>${escapeHtml(s.group_name||s.group_id||'')}</td><td>${escapeHtml(s.snapshot_date)}</td><td>${escapeHtml(s.original_filename)}</td><td>${escapeHtml(s.uploaded_at)}</td><td><button class="secondary" data-download-snapshot="${escapeHtml(s.snapshot_id)}" data-file="${escapeHtml(s.original_filename)}">下载</button></td></tr>`).join('')||'<tr><td colspan="6">暂无小组汇总表</td></tr>';renderSnapshotGroupOptions()}
function renderSnapshotGroupOptions(){
  const wrap=$('#snapshotGroupWrap'),select=$('#snapshotGroup');
  if(!wrap||!select||!state.user)return;
  if(state.user.role==='group_leader'){
    select.innerHTML=`<option value="${escapeHtml(state.user.group_id)}">${escapeHtml(state.user.group_name||state.user.group_id)}</option>`;
    select.disabled=true;select.required=false;
  }else if(state.user.role==='director'){
    select.innerHTML=groupOptions('',state.user.department_id,true);select.disabled=false;select.required=true;
  }else{
    select.innerHTML='<option value="">—</option>';select.disabled=true;select.required=false;
  }
}
function taskConsoleParams(){const params=new URLSearchParams({view:state.taskConsoleView,limit:'50'});const values={status:$('#consoleStatus')?.value,creator:$('#consoleCreator')?.value,trigger_source:$('#consoleTrigger')?.value,q:$('#consoleQuery')?.value.trim()};for(const[k,v]of Object.entries(values))if(v)params.set(k,v);return params}
function renderConsoleCreatorOptions(){const select=$('#consoleCreator');if(!select)return;const current=select.value;select.innerHTML='<option value="">全部创建人</option>'+state.users.filter(u=>u.role!=='employee'||u.enabled).map(u=>`<option value="${escapeHtml(u.user_id)}">${escapeHtml(u.display_name||u.username)} · ${escapeHtml(u.username)}</option>`).join('');select.value=current}
function durationText(seconds){const value=Math.max(0,Number(seconds||0));if(value<60)return `${Math.floor(value)} 秒`;if(value<3600)return `${Math.floor(value/60)} 分 ${Math.floor(value%60)} 秒`;return `${Math.floor(value/3600)} 小时 ${Math.floor(value%3600/60)} 分`}
function formatBytes(value){const bytes=Math.max(0,Number(value||0));if(bytes<1024)return `${Math.round(bytes)} B`;const units=['KB','MB','GB','TB'];let amount=bytes/1024,index=0;while(amount>=1024&&index<units.length-1){amount/=1024;index++}return `${amount.toFixed(amount>=100?0:amount>=10?1:2)} ${units[index]}`}
function monitorValue(value,suffix='%'){const number=Number(value);return Number.isFinite(number)?`${number.toFixed(number>=10?1:2)}${suffix}`:'—'}
function setPressureBar(selector,value,max=100){const node=$(selector),percent=Math.max(0,Math.min(100,Number(value||0)/max*100));node.style.width=`${percent}%`;node.classList.toggle('warn',percent>=85&&percent<95);node.classList.toggle('danger',percent>=95)}
function renderSparkline(node,values,maxValue=100){const clean=values.map(Number).filter(Number.isFinite);if(clean.length<2){node.innerHTML='<span class="chart-empty">等待分钟历史数据</span>';return}const width=260,height=54,max=Math.max(maxValue,...clean,1),step=width/(clean.length-1),points=clean.map((value,index)=>`${(index*step).toFixed(1)},${(height-Math.min(max,value)/max*(height-5)-2).toFixed(1)}`).join(' ');node.innerHTML=`<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="${escapeHtml(node.getAttribute('aria-label')||'历史曲线')}"><line x1="0" y1="${height-2}" x2="${width}" y2="${height-2}" stroke="#d9e2ee" stroke-width="1"/><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`}
function renderResourceCharts(){const points=state.resourceHistory||[];$$('[data-resource-chart]').forEach(node=>{const key=node.dataset.resourceChart,values=points.map(point=>key==='io_pressure'?Number(point.host?.pressure?.io?.some_avg10||0):Number(point.host?.[key]||0));renderSparkline(node,values,key==='io_pressure'?25:100)})}
function dependencyCard(label,value,note,bad=false){if(label==='JPlag / Java')return '';return `<article class="dependency-item ${bad?'bad':''}"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong><small>${escapeHtml(note)}</small></article>`}
function renderResourceSnapshot(){const data=state.resourceSnapshot;if(!data)return;const diagnoses=data.diagnoses||[],top=diagnoses[0],status=data.overall_status||'healthy',verdict=$('#resourceVerdict');verdict.dataset.status=status;$('#resourceVerdictTitle').textContent=top?.title||(status==='healthy'?'当前未发现资源瓶颈':'资源状态需要关注');$('#resourceVerdictEvidence').textContent=top?.evidence||'容器、worker、任务队列和依赖指标均在当前阈值内。';$('#resourceCollectedAt').textContent=`采集 ${formatTimestamp(data.collected_at)||'—'}`;const sources=data.source_status||{},collector=sources.collector||'unknown';$('#resourceSourceState').textContent=collector==='online'?'Docker 与主机采集在线':collector==='disabled'?'资源侧车未启用':'资源侧车降级';$('#resourceDiagnosisCount').textContent=`${diagnoses.length} 项`;$('#resourceDiagnosisList').innerHTML=diagnoses.length?diagnoses.map(item=>`<article class="diagnosis-item ${escapeHtml(item.severity)}"><div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.evidence)}</p><p class="diagnosis-action">建议：${escapeHtml(item.recommendation)}</p></div></article>`).join(''):'<div class="monitor-empty">当前未发现达到阈值的异常。继续采集历史数据后，持续压力判断会更准确。</div>';const host=data.host||{},io=Number(host.pressure?.io?.some_avg10||0);$('#resourceHostCpu').textContent=monitorValue(host.cpu_percent);$('#resourceHostMemory').textContent=monitorValue(host.memory_percent);$('#resourceHostDisk').textContent=host.disk_total_bytes?`${monitorValue(host.disk_percent)} · 余 ${formatBytes(host.disk_free_bytes)}`:'—';$('#resourceHostIo').textContent=monitorValue(io);setPressureBar('#resourceHostCpuBar',host.cpu_percent);setPressureBar('#resourceHostMemoryBar',host.memory_percent);setPressureBar('#resourceHostDiskBar',host.disk_percent);setPressureBar('#resourceHostIoBar',io,25);const tasks=data.tasks||{},counts=tasks.counts||{},worker=tasks.worker||{},llm=data.dependencies?.llm||{};$('#chainQueueNote').textContent=`等待任务 ${Number(counts.queued||0)}`;$('#chainWorkerNote').textContent=worker.online?`在线 · ${worker.worker_id||'worker'}`:'心跳离线';$('#chainLocalNote').textContent=tasks.active_task_id?`任务 ${tasks.active_task_id}`:'当前空闲';$('#chainLlmNote').textContent=llm.active_count?`${llm.active_count} 个活跃调用`:(llm.enabled?'无活跃调用':'未启用');$('#chainExportNote').textContent=tasks.active_chain_stage==='export'?'正在生成结果':'等待任务完成';$$('[data-chain-stage]').forEach(node=>node.classList.toggle('active',node.dataset.chainStage===tasks.active_chain_stage||(node.dataset.chainStage==='worker'&&tasks.active_chain_stage==='starting')));const dependencies=data.dependencies||{},sqlite=dependencies.sqlite||{},storage=dependencies.storage||{},jplag=dependencies.jplag||{};$('#resourceDependencyGrid').innerHTML=dependencyCard('SQLite',`${Number(sqlite.latency_ms||0).toFixed(1)} ms`,`${formatBytes(sqlite.size_bytes)} 数据文件`,Number(sqlite.latency_ms||0)>100)+dependencyCard('业务存储',formatBytes(storage.root_bytes),storage.available?'目录可访问':'目录不可访问',!storage.available)+dependencyCard('JPlag / Java',jplag.enabled?(jplag.jar_available&&jplag.java_available?'可用':'不完整'):'未启用',`JAR ${jplag.jar_available?'就绪':'缺失'} · Java ${jplag.java_available?'就绪':'缺失'}`,jplag.enabled&&(!jplag.jar_available||!jplag.java_available))+dependencyCard('大模型',llm.enabled?(llm.active_count?`${llm.active_count} 个调用中`:`P95 ${(Number(llm.p95_ms||0)/1000).toFixed(1)} 秒`):'未启用',llm.sample_count?`${llm.sample_count} 次样本 · ${llm.error_count||0} 次失败`:'暂无实际调用样本',llm.sample_count>=5&&Number(llm.error_count||0)/Number(llm.sample_count)>.2);const containers=data.containers||[];$('#resourceContainerList').innerHTML=containers.map(item=>{const bad=item.state!=='running'||item.health==='unhealthy',warn=!bad&&(Number(item.memory_percent||0)>=85||Number(item.cpu_percent||0)>=85),stateClass=bad?'bad':warn?'warn':'';return `<tr><td><span class="container-name">${escapeHtml(item.name)}</span></td><td><span class="container-state ${stateClass}">${escapeHtml(item.state||'unknown')} · ${escapeHtml(item.health||'unknown')}</span></td><td>${monitorValue(item.cpu_percent)} / ${Number(item.cpu_limit_cores||0).toFixed(1)} 核</td><td>${monitorValue(item.memory_percent)}<br><span class="small-note">${formatBytes(item.memory_usage_bytes)} / ${formatBytes(item.memory_limit_bytes)}</span></td><td>${monitorValue(item.cpu_throttled_percent)}</td><td>读 ${formatBytes(item.block_read_bytes)}<br>写 ${formatBytes(item.block_write_bytes)}</td><td>收 ${formatBytes(item.network_rx_bytes)}<br>发 ${formatBytes(item.network_tx_bytes)}</td><td>${Number(item.restart_count||0)}${item.oom_killed?' · OOM':''}</td></tr>`}).join('')||'<tr><td colspan="8">Docker 指标不可用；任务与依赖状态仍在继续刷新。</td></tr>';renderResourceCharts()}
async function refreshResourceSnapshot(quiet=false){if(!isAdmin())return;if(!quiet)setAdminMessage('#resourceMonitorMessage','正在读取容器、任务和依赖状态…');state.resourceSnapshot=await requestJson('/api/admin/resource-monitor/snapshot');renderResourceSnapshot();if(!quiet)setAdminMessage('#resourceMonitorMessage',`状态已更新 · ${formatTimestamp(state.resourceSnapshot.collected_at)}`)}
async function refreshResourceHistory(quiet=false){if(!isAdmin())return;const data=await requestJson(`/api/admin/resource-monitor/history?range=${encodeURIComponent(state.resourceRange)}`);state.resourceHistory=data.points||[];const labels={'1h':'最近 1 小时','6h':'最近 6 小时','24h':'最近 24 小时','7d':'最近 7 天'};$('#resourceHistoryNote').textContent=`${labels[state.resourceRange]} · 每分钟 · ${state.resourceHistory.length} 个点`;renderResourceCharts();if(!quiet&&data.source_status?.collector!=='online')setAdminMessage('#resourceMonitorMessage','历史采集侧车暂不可用，当前应用状态仍会刷新。')}
