function taskElapsedSeconds(task){const start=Date.parse(task.started_at||task.queued_at||task.created_at||''),end=Date.parse(task.finished_at||'');if(Number.isNaN(start))return 0;return Math.max(0,((Number.isNaN(end)?Date.now():end)-start)/1000)}
function taskConsoleActionButton(action,task){const labels={pause:'暂停',resume:'恢复',restart:'重启',force_terminate:task.status==='paused'?'终止任务':'强制终止'},danger=action==='force_terminate'?' danger-button':' secondary';return `<button type="button" class="${danger.trim()}" data-console-action="${action}" data-console-task="${escapeHtml(task.task_id)}" data-console-name="${escapeHtml(taskName(task))}">${labels[action]}</button>`}
function renderTaskConsole(){const list=$('#taskConsoleList'),tasks=state.taskConsoleTasks||[];list.innerHTML=tasks.map((task,index)=>{const status=task.effective_status||task.status,percent=Math.max(0,Math.min(100,Number(task.progress_percent||0))),scope=[task.payload?.report_date_start,task.payload?.report_date_end].filter(Boolean).join(' 至 ')||task.report_date||'未指定',position=task.queue_position?`Q${String(task.queue_position).padStart(2,'0')}`:status==='running'||status==='pausing'||status==='terminating'?'RUN':String(index+1).padStart(2,'0'),actions=(task.allowed_actions||[]).map(action=>taskConsoleActionButton(action,task)).join(''),meta=[task.creator_department_name,task.creator_group_name].filter(Boolean).join(' / ')||'全公司',attempt=`第 ${Number(task.current_attempt||1)} 次尝试`,partial=task.partial_available?'<span class="partial-note">已保留部分结果</span>':'';return `<article class="queue-task" data-status="${escapeHtml(status)}"><div class="queue-marker" aria-label="${task.queue_position?`队列第 ${task.queue_position} 位`:'任务节点'}"><span>${escapeHtml(position)}</span></div><div class="queue-task-body"><div class="queue-task-head"><div><div class="queue-title-line"><h2>${escapeHtml(taskName(task))}</h2><span class="task-state ${escapeHtml(status)}">${escapeHtml(taskStatusText(status))}</span>${partial}</div><p class="queue-task-id">${escapeHtml(task.task_id)} · ${task.trigger_source==='system_daily'?'系统自动任务':'手工任务'}</p></div><div class="queue-task-actions">${actions||'<span class="small-note">当前无需操作</span>'}</div></div><div class="queue-task-meta"><span><b>创建人</b>${escapeHtml(task.creator_name||'系统')} · ${escapeHtml(task.creator_username||'system')}</span><span><b>组织</b>${escapeHtml(meta)}</span><span><b>范围</b>${escapeHtml(scope)}</span><span><b>运行时长</b>${escapeHtml(durationText(taskElapsedSeconds(task)))}</span><span><b>尝试</b>${escapeHtml(attempt)}</span></div><div class="task-progress-line"><div class="task-progress-copy"><span>${escapeHtml(task.progress_message||taskStatusText(status))}</span><strong>${Number(task.progress_current||0)}/${Number(task.progress_total||0)} · ${percent.toFixed(percent%1?1:0)}%</strong></div><div class="task-progress-track ${task.progress_total?'':'indeterminate'}" role="progressbar" aria-label="${escapeHtml(taskName(task))}进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent}" aria-valuetext="${escapeHtml(task.progress_message||taskStatusText(status))}"><span style="width:${percent}%"></span></div></div>${task.error_message?`<p class="task-error-note">${escapeHtml(task.error_message)}</p>`:''}</div></article>`}).join('')||`<div class="task-console-empty"><strong>${state.taskConsoleView==='active'?'队列当前为空':'没有符合筛选条件的历史任务'}</strong><span>${state.taskConsoleView==='active'?'新的查重任务进入队列后会自动出现在这里。':'调整状态、创建人或关键词后重新查询。'}</span></div>`;$('#taskConsoleLoadMore').classList.toggle('hidden',!state.taskConsoleCursor);$('#taskConsoleResultNote').textContent=`已显示 ${tasks.length} 个${state.taskConsoleView==='active'?'活动':'历史'}任务`}
async function refreshTaskConsole(reset=true,quiet=false){if(!isAdmin())return;const params=taskConsoleParams();if(!reset&&state.taskConsoleCursor)params.set('cursor',state.taskConsoleCursor);if(!quiet)setAdminMessage('#taskConsoleMessage','正在同步任务队列…');const data=await requestJson('/api/admin/task-console?'+params);state.taskConsoleTasks=reset?(data.tasks||[]):state.taskConsoleTasks.concat(data.tasks||[]);state.taskConsoleCursor=data.next_cursor||'';const counts=data.counts||{};$('#consoleRunningCount').textContent=counts.running||0;$('#consoleQueuedCount').textContent=counts.queued||0;$('#consolePausedCount').textContent=counts.paused||0;$('#consoleAbnormalCount').textContent=counts.abnormal||0;const worker=data.worker||{},strip=$('#taskWorkerStrip');strip.classList.toggle('offline',!worker.online);$('#taskWorkerState').textContent=worker.online?'后台 worker 在线':'后台 worker 离线';$('#taskWorkerMeta').textContent=worker.online?`${worker.worker_id||'worker'} · 心跳 ${formatTimestamp(worker.heartbeat_at)}`:(worker.heartbeat_at?`最后心跳 ${formatTimestamp(worker.heartbeat_at)}；排队任务暂不会启动`:'尚未检测到 worker 心跳；请检查 worker 服务');renderTaskConsole();if(!quiet)setAdminMessage('#taskConsoleMessage',`同步完成 · ${formatTimestamp(data.refreshed_at)}`)}
function stopTaskConsolePolling(){if(state.taskConsoleTimer){clearTimeout(state.taskConsoleTimer);state.taskConsoleTimer=null}}
function scheduleTaskConsolePolling(){stopTaskConsolePolling();if(!isAdmin()||state.taskConsoleView!=='active'||document.hidden||$('.panel.active')?.id!=='taskConsole')return;state.taskConsoleTimer=setTimeout(async()=>{try{await refreshTaskConsole(true,true)}catch(err){setAdminMessage('#taskConsoleMessage',err.message)}scheduleTaskConsolePolling()},2000)}
async function activateTaskConsole(){try{await refreshTaskConsole(true)}catch(err){setAdminMessage('#taskConsoleMessage',err.message)}scheduleTaskConsolePolling()}
async function setTaskConsoleView(view){state.taskConsoleView=view;state.taskConsoleCursor='';state.taskConsoleTasks=[];$('#consoleStatus').value='';$('#taskConsoleActive').classList.toggle('active',view==='active');$('#taskConsoleHistory').classList.toggle('active',view==='history');$('#taskConsoleActive').setAttribute('aria-pressed',view==='active'?'true':'false');$('#taskConsoleHistory').setAttribute('aria-pressed',view==='history'?'true':'false');$('#taskConsoleRefreshNote').textContent=view==='active'?'活动页每 2 秒自动刷新':'历史页按需加载';stopTaskConsolePolling();await refreshTaskConsole(true);scheduleTaskConsolePolling()}
async function runTaskConsoleAction(button){const action=button.dataset.consoleAction,taskId=button.dataset.consoleTask,name=button.dataset.consoleName||taskId;if(action==='pause'&&!confirm(`暂停“${name}”吗？系统会等待当前批次完成并保存检查点。`))return;if(action==='resume'&&!confirm(`从检查点恢复“${name}”吗？任务会重新进入队列。`))return;if(action==='restart'&&!confirm(`从头重启“${name}”吗？当前 attempt 的部分结果会保留在历史中。`))return;const payload={};if(action==='force_terminate'){const confirmation=prompt(`强制终止会立即结束任务进程。请输入任务 ID 确认：\n${taskId}`);if(confirmation!==taskId){setAdminMessage('#taskConsoleMessage','任务 ID 不匹配，已取消强制终止。');return}payload.confirmation_task_id=taskId}button.disabled=true;setAdminMessage('#taskConsoleMessage',`正在执行：${button.textContent}…`);try{const endpoint=action==='force_terminate'?'force-terminate':action;await requestJson(`/api/admin/tasks/${encodeURIComponent(taskId)}/${endpoint}`,{method:'POST',body:JSON.stringify(payload)});await refreshTaskConsole(true);scheduleTaskConsolePolling()}finally{button.disabled=false}}
