function renderDepartments(){state.departments.sort((a,b)=>String(a.name).localeCompare(String(b.name),'zh-CN'));$('#departmentList').innerHTML=state.departments.map(d=>`<tr><td>${escapeHtml(d.department_id)}</td><td><input data-dept="${escapeHtml(d.department_id)}" data-field="name" value="${escapeHtml(d.name)}" /></td><td><input data-dept="${escapeHtml(d.department_id)}" data-field="parent_department_id" value="${escapeHtml(d.parent_department_id||'')}" /></td><td class="user-status-cell"><input class="user-status-toggle" type="checkbox" data-dept="${escapeHtml(d.department_id)}" data-field="enabled" ${d.enabled?'checked':''}/></td><td class="user-actions"><div class="user-action-group"><button type="button" class="secondary" data-save-dept="${escapeHtml(d.department_id)}">保存</button><button type="button" class="danger-button" data-delete-dept="${escapeHtml(d.department_id)}">删除</button></div></td></tr>`).join('');$('#userDepartment').innerHTML=departmentOptions('',true);$('#groupDepartment').innerHTML=departmentOptions('',true)}
