function updateAdminGroupOptions(){const did=$('#userDepartment').value;$('#userGroup').innerHTML=groupOptions('',did,true)}
function applyUserFormRules(){const role=$('#userRole').value,department=$('#userDepartment'),group=$('#userGroup');const noDepartment=['minister','admin'].includes(role);department.disabled=noDepartment;department.required=!noDepartment;group.disabled=noDepartment||role==='director';group.required=['employee','group_leader'].includes(role);if(noDepartment)department.value='';if(group.disabled)group.value=''}
async function refreshUsers(){state.users=await requestJson('/api/users');$('#userList').innerHTML=state.users.map(u=>`<tr><td>${escapeHtml(u.username)}</td><td><input data-user="${escapeHtml(u.user_id)}" data-field="display_name" value="${escapeHtml(u.display_name)}" /></td><td><select data-user="${escapeHtml(u.user_id)}" data-field="role">${roleOptions(u.role)}</select></td><td><select data-user="${escapeHtml(u.user_id)}" data-field="department_id">${departmentOptions(u.department_id,true)}</select></td><td><select data-user="${escapeHtml(u.user_id)}" data-field="group_id">${groupOptions(u.group_id,u.department_id,true)}</select></td><td class="user-manager-cell">${escapeHtml(u.manager_display_name||'—')}</td><td class="user-status-cell"><input class="user-status-toggle" type="checkbox" data-user="${escapeHtml(u.user_id)}" data-field="enabled" ${u.enabled?'checked':''}/></td><td class="user-actions"><div class="user-action-group"><button class="secondary" data-save-user="${escapeHtml(u.user_id)}">保存</button><button class="secondary" data-reset-user="${escapeHtml(u.user_id)}" data-reset-username="${escapeHtml(u.username)}">重置密码</button><button class="danger-button" data-delete-user="${escapeHtml(u.user_id)}">删除</button></div></td></tr>`).join('');renderConsoleCreatorOptions()}
function openPasswordResetDialog(userId,username){const dialog=$('#passwordResetDialog'),form=$('#passwordResetForm');form.reset();$('#passwordResetUserId').value=userId;$('#passwordResetUsername').textContent=username;$('#passwordResetMessage').textContent='';if(typeof dialog.showModal==='function')dialog.showModal();else dialog.setAttribute('open','');$('#passwordResetNew').focus()}
function shanghaiDateValue(date){const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`}
function ensureAuditDates(){if(state.auditDatesInitialized)return;const nowMs=state.serverClock.baseMs?state.serverClock.baseMs+Date.now()-state.serverClock.receivedAt:Date.now();$('#auditEnd').value=shanghaiDateValue(new Date(nowMs));$('#auditStart').value=shanghaiDateValue(new Date(nowMs-6*86400000));state.auditDatesInitialized=true}
function auditFilterParams(){const params=new URLSearchParams();for(const id of ['auditStart','auditEnd','auditCategory','auditSeverity','auditOutcome']){const el=$('#'+id),key={auditStart:'start',auditEnd:'end',auditCategory:'category',auditSeverity:'severity',auditOutcome:'outcome'}[id];if(el?.value)params.set(key,el.value)}const q=$('#auditQuery')?.value.trim();if(q)params.set('q',q);return params}
function auditSeverityText(v){return {critical:'严重',warning:'警告',info:'信息'}[v]||v}
function auditOutcomeText(v){return {success:'成功',failure:'失败'}[v]||v}
function auditActionText(v){return {'auth.login':'登录','auth.logout':'登出','auth.register':'自助注册','admin.user.create':'新增账号','admin.user.update':'修改账号','admin.user.delete':'删除账号','admin.user.password_reset':'重置密码','admin.department.create':'新增部门','admin.department.update':'修改部门','admin.department.delete':'删除部门','admin.group.create':'新增小组','admin.group.update':'修改小组','admin.group.delete':'删除小组','admin.settings.update':'修改系统参数','admin.llm.test':'测试 LLM 连接','admin.sessions.cleanup':'清理过期会话','admin.reset.prepare':'准备清除业务数据','admin.reset.confirm':'清除业务数据','task.create':'创建查重任务','task.retry':'重试查重任务','task.cancel':'取消查重任务','task.pause':'暂停查重任务','task.resume':'恢复查重任务','task.restart':'重启查重任务','task.force_terminate':'强制终止查重任务','task.delete':'删除查重任务','report.update':'修改日报','snapshot.upsert':'上传或替换测试总表','export.weekly':'导出日报汇总','export.periodic':'导出周期报表','export.task_result':'导出查重结果','audit.export':'导出审查日志'}[v]||v}
function renderAuditLogs(){const rows=state.auditLogs||[];$('#auditLogList').innerHTML=rows.map(row=>{const actor=row.actor_display_name||row.actor_username||'未知账号',actorMeta=row.actor_username&&row.actor_display_name!==row.actor_username?`<br><span class="small-note">${escapeHtml(row.actor_username)} · ${escapeHtml(roleText(row.actor_role))}</span>`:`<br><span class="small-note">${escapeHtml(roleText(row.actor_role)||'—')}</span>`,target=[row.target_label,row.target_id].filter(Boolean).join(' · ')||row.target_type||'—',details={脱敏差异:row.changes||{},错误:row.error_type||'',客户端:row.user_agent||''};return `<tr><td class="audit-time">${escapeHtml(formatTimestamp(row.occurred_at))}</td><td><span class="audit-badge ${escapeHtml(row.severity)}">${escapeHtml(auditSeverityText(row.severity))}</span></td><td><span class="audit-result ${escapeHtml(row.outcome)}">${escapeHtml(auditOutcomeText(row.outcome))}</span></td><td>${escapeHtml(actor)}${actorMeta}</td><td>${escapeHtml(auditActionText(row.action))}<br><span class="small-note">${escapeHtml(row.category)}</span></td><td>${escapeHtml(target)}</td><td>${escapeHtml(row.client_ip||'—')}</td><td>${escapeHtml(row.summary||'')}</td><td><details class="audit-details"><summary>查看</summary><pre>${escapeHtml(JSON.stringify(details,null,2))}</pre></details></td></tr>`}).join('')||'<tr><td colspan="9">当前筛选范围内暂无审查日志</td></tr>';$('#auditLoadMore').classList.toggle('hidden',!state.auditCursor)}
async function refreshAuditLogs(reset=true){if(!isAdmin())return;ensureAuditDates();const params=auditFilterParams();params.set('limit','50');if(!reset&&state.auditCursor)params.set('cursor',state.auditCursor);setAdminMessage('#auditMessage','加载中...');const data=await requestJson('/api/admin/audit-logs?'+params);state.auditLogs=reset?(data.items||[]):state.auditLogs.concat(data.items||[]);state.auditCursor=data.next_cursor||'';const stats=data.stats||{};$('#auditTotal').textContent=stats.total||0;$('#auditFailed').textContent=stats.failed||0;$('#auditCritical').textContent=stats.critical||0;$('#auditLoginFailed').textContent=stats.login_failed||0;renderAuditLogs();setAdminMessage('#auditMessage',`已显示 ${state.auditLogs.length} 条`)}
function runtimeLogFilterParams(){const params=new URLSearchParams(),fields={runtimeLogStart:'start',runtimeLogEnd:'end',runtimeLogLevel:'level',runtimeLogSource:'source',runtimeLogTaskId:'task_id'};for(const[id,key]of Object.entries(fields)){const value=$('#'+id)?.value.trim();if(value)params.set(key,value)}const q=$('#runtimeLogQuery')?.value.trim();if(q)params.set('q',q);return params}
function runtimeLevelText(level){return {info:'信息',warning:'警告',error:'错误'}[level]||level||'信息'}
function runtimeSourceText(source){return {web:'Web',worker:'Worker',scheduler:'调度器',task:'任务',llm:'LLM',monitor:'监控'}[source]||source||'系统'}
function setRuntimeStreamState(label,mode=''){const stateEl=$('#runtimeStreamState'),dot=$('#runtimeStreamDot')?.parentElement;if(stateEl)stateEl.textContent=label;if(dot){dot.classList.toggle('live',mode==='live');dot.classList.toggle('reconnecting',mode==='reconnecting')}}
function runtimeDetailsText(row){return JSON.stringify({事件:row.event||'',上下文:row.context||{},异常堆栈:row.traceback||''},null,2)}
function renderRuntimeLogs(){const rows=state.runtimeLogs||[];$('#runtimeLogList').innerHTML=rows.map(row=>{const detail=runtimeDetailsText(row),task=row.task_id?`${row.task_id}${row.attempt_no?` · 第 ${row.attempt_no} 次`:''}`:'—';return `<tr data-runtime-seq="${escapeHtml(row.seq)}"><td class="runtime-time">${escapeHtml(formatTimestamp(row.occurred_at))}</td><td><span class="runtime-level ${escapeHtml(row.level)}">${escapeHtml(runtimeLevelText(row.level))}</span></td><td><span class="runtime-source">${escapeHtml(runtimeSourceText(row.source))}</span></td><td>${escapeHtml(row.event||'—')}</td><td>${escapeHtml(task)}</td><td class="runtime-message">${escapeHtml(row.message||'—')}</td><td><details class="runtime-details"><summary>查看</summary><pre>${escapeHtml(detail)}</pre><button class="runtime-copy" type="button" data-copy-runtime="${escapeHtml(row.seq)}">复制此条</button></details></td></tr>`}).join('')||'<tr><td colspan="7">当前筛选范围内暂无运行日志</td></tr>';$('#runtimeLogLoadMore').classList.toggle('hidden',!state.runtimeCursor)}
function appendRuntimeLog(row){const seq=Number(row?.seq||0);if(!seq||state.runtimeLogs.some(item=>Number(item.seq)===seq))return;state.runtimeLogs.push(row);state.runtimeLogs.sort((a,b)=>Number(a.seq)-Number(b.seq));if(state.runtimeLogs.length>300)state.runtimeLogs=state.runtimeLogs.slice(-300);state.runtimeLastSeq=Math.max(state.runtimeLastSeq,seq);renderRuntimeLogs();if($('#runtimeLogFollow')?.checked){const node=$(`[data-runtime-seq="${seq}"]`);node?.scrollIntoView({block:'nearest',behavior:'smooth'})}}
function stopRuntimeLogStream(){if(state.runtimeStream){state.runtimeStream.close();state.runtimeStream=null}if($('.panel.active')?.id!=='runtimeLogs')setRuntimeStreamState('已暂停')}
async function refreshRuntimeLogs(reset=true){if(!isAdmin())return;const params=runtimeLogFilterParams();params.set('limit','100');if(!reset&&state.runtimeCursor)params.set('cursor',state.runtimeCursor);setAdminMessage('#runtimeLogMessage','正在加载日志…');const data=await requestJson('/api/admin/runtime-logs?'+params);state.runtimeLogs=reset?(data.items||[]):[...(data.items||[]),...state.runtimeLogs];state.runtimeLogs.sort((a,b)=>Number(a.seq)-Number(b.seq));state.runtimeCursor=data.next_cursor||'';state.runtimeLastSeq=Math.max(Number(data.latest_seq||0),...state.runtimeLogs.map(row=>Number(row.seq)||0),0);renderRuntimeLogs();setAdminMessage('#runtimeLogMessage',`已显示 ${state.runtimeLogs.length} 条；实时连接会自动恢复。`)}
function startRuntimeLogStream(){stopRuntimeLogStream();if(!isAdmin()||document.hidden||$('.panel.active')?.id!=='runtimeLogs')return;const params=runtimeLogFilterParams();params.set('after',String(state.runtimeLastSeq||0));const stream=new EventSource('/api/admin/runtime-logs/stream?'+params);state.runtimeStream=stream;setRuntimeStreamState('正在连接…','reconnecting');stream.addEventListener('open',()=>setRuntimeStreamState('实时连接中','live'));stream.addEventListener('runtime_log',event=>{try{appendRuntimeLog(JSON.parse(event.data));setRuntimeStreamState('实时连接中','live')}catch(_err){}});stream.addEventListener('error',()=>{if(state.runtimeStream===stream)setRuntimeStreamState('连接中断，正在重连…','reconnecting')})}
async function activateRuntimeLogs(){try{await refreshRuntimeLogs(true);startRuntimeLogStream()}catch(err){setAdminMessage('#runtimeLogMessage',err.message);setRuntimeStreamState('无法连接','reconnecting')}}
function settingLabel(k){return {'daily_report_submission.rollover_time':'日报归属切换时间','automatic_daily_duplicate.enabled':'启用自动查重任务','automatic_daily_duplicate.run_at':'自动查重任务时间','daily_duplicate.report_worker_count':'日报检查并行数（1-8）','daily_duplicate.llm_candidate_top_n':'大模型候选数 Top-N','daily_duplicate.llm_candidate_score_threshold':'候选最低分','daily_duplicate.low_info_candidate_score_threshold':'低信息候选分','daily_duplicate.max_candidates':'最大召回候选数','daily_duplicate.self_history_days':'本人历史天数','daily_duplicate.cross_user_days':'跨人近几天','daily_duplicate.cross_user_scope':'跨人范围','daily_duplicate.score_weights.text':'文本权重','daily_duplicate.score_weights.semantic':'语义权重','daily_duplicate.score_weights.recency':'时间权重','llm_judge.enabled':'启用大模型','llm_judge.base_url':'模型 Base URL','llm_judge.chat_path':'模型路径','llm_judge.model':'模型名','llm_judge.api_key_file':'API Key 文件路径','llm_judge.api_key_env':'API Key 环境变量（兼容）','testcase_verification.enabled':'启用测试用例核验','testcase_verification.self_history_days':'测试用例本人历史天数','testcase_verification.self_history_high_rate':'测试用例查重高风险阈值(0-1)','testcase_verification.self_history_medium_rate':'测试用例查重中风险阈值(0-1)','checks.enable_code_check':'启用代码记录检查','checks.enable_document_check':'启用文档记录检查','checks.code_token_similarity_threshold':'代码 Token 查重中风险阈值(0-1)','checks.code_token_high_risk_threshold':'代码 Token 查重高风险阈值(0-1)','checks.document_token_similarity_threshold':'文档 Token 查重中风险阈值(0-1)','checks.document_token_high_risk_threshold':'文档 Token 查重高风险阈值(0-1)','upload.max_file_mb':'上传大小 MB'}[k]||k}
